from sqlalchemy import select,func
from app.database import SessionLocal
from app.models import Source,SourceOpportunity,SourceOpportunityDatasetMembership,SyncJob,SourceObservation,Opportunity,QualificationReview,ChangeHistory
import json
with SessionLocal() as db:
 s=db.scalar(select(Source).where(Source.source_key=='invest-saudi'))
 rows=db.execute(select(SourceOpportunity.id,SourceOpportunity.source_opportunity_id,SourceOpportunity.official_source_id_original,SourceOpportunity.official_source_id_normalized,SourceOpportunity.canonical_status,SourceOpportunity.missing_successful_checks,SourceOpportunity.last_missing_at,SourceOpportunity.last_seen_at,SourceOpportunity.master_opportunity_id,SourceOpportunity.raw_data_json,SourceOpportunity.standardized_data_json,SourceOpportunity.parser_version,SourceOpportunityDatasetMembership.dataset_name,SourceOpportunityDatasetMembership.endpoint,SourceOpportunityDatasetMembership.is_current,SourceOpportunityDatasetMembership.missing_successful_checks,SourceOpportunityDatasetMembership.last_seen_at).join(SourceOpportunityDatasetMembership,SourceOpportunityDatasetMembership.source_opportunity_id==SourceOpportunity.id).where(SourceOpportunity.source_id==s.id)).all()
 out=[]
 for r in rows:
  out.append({'id':r[0],'external_id':r[1],'official_original':r[2],'official_normalized':r[3],'status':r[4],'missing_checks':r[5],'last_missing_at':str(r[6]) if r[6] else None,'last_seen_at':str(r[7]),'master_id':r[8],'raw':r[9],'standardized':r[10],'parser_version':r[11],'dataset':r[12],'endpoint':r[13],'is_current':r[14],'membership_checks':r[15],'membership_last_seen':str(r[16])})
 with open('/tmp/job439-current-memberships.json','w',encoding='utf-8') as f:json.dump(out,f,ensure_ascii=False)
 print(json.dumps({'rows':len(out),'mmasters_total':db.scalar(select(func.count()).select_from(Opportunity)),'masters_current':db.scalar(select(func.count()).select_from(Opportunity).where(Opportunity.status!='MERGED')),'masters_merged':db.scalar(select(func.count()).select_from(Opportunity).where(Opportunity.status=='MERGED')),'source_opportunities':db.scalar(select(func.count()).select_from(SourceOpportunity)),'invest_saudi_rows':db.scalar(select(func.count()).select_from(SourceOpportunity).where(SourceOpportunity.source_id==s.id)),'observations_total':db.scalar(select(func.count()).select_from(SourceObservation)),'open_reviews':db.scalar(select(func.count()).select_from(QualificationReview).where(QualificationReview.status=='OPEN')),'sync_jobs_total':db.scalar(select(func.count()).select_from(SyncJob)),'investsaudi_observations':db.scalar(select(func.count()).select_from(SourceObservation).join(SourceOpportunity).where(SourceOpportunity.source_id==s.id))},default=str))
